ssize_t socket_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int err = 0;
    ssize_t ret = 0;

    if (sock->sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (count > 0xFFFF)
        count = 0xFFFF;

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        if (file->f_flags & O_NONBLOCK)
            return -EAGAIN;

        wait_for_data(sock);
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        if (!skb)
            return -EAGAIN;
    }

    if (skb->len < count)
        count = skb->len;

    if (copy_to_user(buf, skb->data, count)) {
        err = -EFAULT;
        goto out;
    }

    ret = count;
    sock->sk->sk_data_processed += count;
    sock->sk->sk_forward_alloc = 0;
    sock->sk->sk_err = 0;
    sock->sk->sk_state = TCP_ESTABLISHED;

out:
    kfree_skb(skb);
    return (err) ? err : ret;
}

ssize_t socket_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied;
    ssize_t ret = -EAGAIN;

    if ((file->f_flags & O_NONBLOCK) && skb_queue_empty(&sk->sk_receive_queue))
        return ret;

    if (!buf || count > INT_MAX || count == 0)
        return -EINVAL;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = skb->len;
    if (count > copied)
        count = copied;

    if (copy_to_user(buf, skb->data, count)) {
        ret = -EFAULT;
        goto out;
    }

    ret = count;

out:
    kfree_skb(skb);
    return ret;
}

ssize_t read_from_socket(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int err = 0;
    ssize_t ret;

    if (sock->sk->sk_type == SOCK_DGRAM && sock->sk->sk_state != TCP_ESTABLISHED) {
        if (sock->sk->sk_shutdown & RCV_SHUTDOWN) {
            return 0;
        }
        if (file->f_flags & O_NONBLOCK && !skb_queue_len(&sock->sk->sk_receive_queue)) {
            return -EAGAIN;
        }
    }

    if (!buf || count == 0) {
        return -EINVAL;
    }

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (count < skb->len) {
        kfree_skb(skb);
        return -EMSGSIZE;
    }

    if (copy_to_user(buf, skb->data, skb->len)) {
        kfree_skb(skb);
        return -EFAULT;
    }

    ret = skb->len;
    kfree_skb(skb);
    return ret;
}

ssize_t read_from_socket(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    ssize_t bytes_read;
    int err;

    if (sock->flags & O_NONBLOCK && skb_queue_empty(&sock->sk->sk_receive_queue)) {
        return -EAGAIN;
    }

    if (!buf || count == 0) {
        return -EINVAL;
    }

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        return -EFAULT;
    }

    bytes_read = min(skb->len, count);

    if (copy_to_user(buf, skb->data, bytes_read)) {
        skb_queue_head(&sock->sk->sk_receive_queue, skb);
        return -EFAULT;
    }

    sock->sk->sk_backlog.len--;

    kfree_skb(skb);

    return bytes_read;
}

ssize_t sock_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int err = 0;
    ssize_t copied = 0;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if ((file->f_flags & O_NONBLOCK) && skb_queue_empty(&sk->sk_receive_queue))
        return -EAGAIN;

    if (!access_ok(buf, count))
        return -EFAULT;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    lock_sock(sk);

    skb = skb_peek(&sk->sk_receive_queue);
    if (skb) {
        int len = min(skb->len, count);
        if (copy_to_user(buf, skb->data, len)) {
            err = -EFAULT;
        } else {
            copied = len;
        }
        skb_unlink(skb, &sk->sk_receive_queue);
        kfree_skb(skb);
    }

    release_sock(sk);

    if (err < 0)
        return err;

    return copied;
}
